from taf.internal.aliasing import aliasing_scope
from taf.selenium.gnb.oam.coam.classical.facade import Coam
from taf.selenium.core.robotkeywords.keywords import SeleniumOAMKeywords
from taf.selenium.gnb.oam.coam.classical.common.debug import catch_interface_exception


class CommissioningClassical(SeleniumOAMKeywords):
    """
    Class includes all kws related to Commissioning Wizard configuration page.
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope(lookup_arg='coam', lookup_type=Coam)

    def __init__(self):
        super(CommissioningClassical, self).__init__()

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def go_to_commissioning_tab(self, target_tab_path, timeout=60, coam=None):
        """
        Go to target which will be configured on commissioning modal

        :param target_tab_path: name of target
        If thre is only one target tab, such as "NR TDD/Basic Cell Settings", "System Module Configuration", directly
        pass this string;
        If there are two same target tabs on modal, such as "Basic Cell Settings", parent target tab should be included
        to locate target tab, such as "Cells Configuration/NR TDD/Basic Cell Settings"
        :type target_tab_path: str
        :param timeout: timeout
        :type timeout: int
        """
        coam.configuration.commissioning_wizard.go_to_target_path_under_commissioning_tab(
            target_tab_path, int(timeout))

    @catch_interface_exception
    @lookup_handler.implicit_lookup
    def submit(self, coam=None):
        coam.configuration.commissioning_wizard.submit()
